package br.com.adminpool.repository;
import br.com.adminpool.model.PedidoProduto; import br.com.adminpool.model.ResponsavelPagamento; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import java.time.LocalDate; import java.util.List;
public interface PedidoProdutoRepository extends JpaRepository<PedidoProduto, Long> { List<PedidoProduto> findAllByOrderByDataPedidoDesc(); List<PedidoProduto> findByClienteIdOrderByDataPedidoDesc(Long clienteId); List<PedidoProduto> findByStatusOrderByDataPedidoDesc(String status); List<PedidoProduto> findByPiscinaResponsavelUsuarioLoginIgnoreCaseOrderByDataPedidoDesc(String login); @Query("select p from PedidoProduto p left join p.piscina pi left join pi.responsavel responsavel left join responsavel.usuario responsavelUsuario left join p.funcionario funcionario left join funcionario.usuario funcionarioUsuario where lower(responsavelUsuario.login) = lower(:login) or lower(funcionarioUsuario.login) = lower(:login) order by p.dataPedido desc") List<PedidoProduto> findVisiveisPorColaborador(@org.springframework.data.repository.query.Param("login") String login); List<PedidoProduto> findByCodigoPedidoOrderByIdAsc(Long codigoPedido); List<PedidoProduto> findByDataConclusaoBetweenOrderByDataConclusaoDesc(LocalDate inicio, LocalDate fim); @Query(value="select nextval('pedido_codigo_seq')",nativeQuery=true) Long proximoCodigoPedido(); }
